/**
 * ControlDesk — stable barrel over the Supabase-generated types.
 *
 * `database.generated.ts` is regenerated by `pnpm db:types` and must NOT
 * be edited by hand. This file adds ergonomic type aliases on top of the
 * generated `Database` schema so callers can write:
 *
 *   import type { CashAdvanceStatus } from "@/types/database";
 *
 * instead of the verbose `Enums<"cash_advance_status">` every time. When
 * new enums appear in the schema, add a matching alias here.
 */

import type { Database } from "./database.generated";

export type { Database, Json, Tables, TablesInsert, TablesUpdate, Enums, CompositeTypes } from "./database.generated";
export { Constants } from "./database.generated";

// ---------------------------------------------------------------------------
// Enum-derived aliases. Names follow PascalCase(snake_case) of the DB enum.
// ---------------------------------------------------------------------------

type E<K extends keyof Database["public"]["Enums"]> = Database["public"]["Enums"][K];

export type AiInsightKind = E<"ai_insight_kind">;
export type AiInsightSeverity = E<"ai_insight_severity">;
