// ---------------------------------------------------------------------------
// Hand-defined types — NOT backed by a Postgres enum. Keep these tight, and
// prefer converting to a real enum when the value set stabilises.
// ---------------------------------------------------------------------------

/**
 * Employee shift/roster daily status. Stored as `text` in `employee_rosters.status`;
 * union kept in sync with the values inserted by the roster upsert action.
 */
export type RosterEntryStatus = "PLANNED" | "LEAVE" | "SICK" | "OFF";

/**
 * Derived severity level for secret-rotation health, computed by
 * `src/lib/security/rotation.ts`. Not a stored enum — purely a UI signal.
 */
export type SecretRotationSeverity = "OK" | "WARN" | "OVERDUE";
